parameters.functionCode:
const proposalData = $input.item.json;
const analysis = JSON.parse($('GPT-4 - Analyze Proposal').item.json.choices[0].message.content);

// Calculate voting power and quorum
const totalVotes = parseFloat(proposalData.for_votes) + parseFloat(proposalData.against_votes) + parseFloat(proposalData.abstain_votes);
const forPercentage = totalVotes > 0 ? (parseFloat(proposalData.for_votes) / totalVotes * 100).toFixed(2) : 0;
const againstPercentage = totalVotes > 0 ? (parseFloat(proposalData.against_votes) / totalVotes * 100).toFixed(2) : 0;

const report = {
  governance_report_id: `gov_${Date.now()}`,
  timestamp: new Date().toISOString(),
  proposal: {
    id: proposalData.proposal_id,
    title: proposalData.title,
    proposer: proposalData.proposer
  },
  voting_status: {
    total_votes: totalVotes,
    for_votes: proposalData.for_votes,
    against_votes: proposalData.against_votes,
    for_percentage: forPercentage,
    against_percentage: againstPercentage,
    current_outcome: forPercentage > 50 ? 'passing' : 'failing'
  },
  ai_recommendation: {
    vote: analysis.vote_recommendation,
    confidence: analysis.confidence,
    analysis: analysis.analysis,
    impact: analysis.potential_impact,
    risks: analysis.risks,
    benefits: analysis.benefits
  },
  auto_vote_decision: analysis.confidence >= 0.8 && analysis.vote_recommendation !== 'abstain'
};

return { json: report };

